using System.Globalization;

namespace Frostbar.Core.Localization;

/// <summary>
/// UI text in Japanese and English. "system" follows the Windows display language (Japanese on the user's PC).
/// Wording follows macOS's Japanese menus where Windows users would still recognise it (ウインドウ, しまう, …).
/// </summary>
public sealed class Strings
{
    public string Language { get; }
    readonly Dictionary<string, string> _map;

    Strings(string lang) { Language = lang; _map = lang == "ja" ? Ja : En; }

    public static Strings For(string setting, CultureInfo uiCulture) =>
        new(setting switch { "ja" => "ja", "en" => "en", _ => uiCulture.TwoLetterISOLanguageName == "ja" ? "ja" : "en" });

    public CultureInfo Culture => CultureInfo.GetCultureInfo(Language == "ja" ? "ja-JP" : "en-US");

    public string this[string key] => _map.TryGetValue(key, out var v) ? v : (En.TryGetValue(key, out var e) ? e : key);
    public string F(string key, params object[] args) => string.Format(Culture, this[key], args);

    public static IReadOnlyCollection<string> JaKeys => Ja.Keys;
    public static IReadOnlyCollection<string> EnKeys => En.Keys;

